package com.sajuppugi.gift.api; import com.sajuppugi.common.api.*; import com.sajuppugi.gift.application.DirectGiftFulfillmentService; import jakarta.validation.constraints.*; import org.springframework.boot.autoconfigure.condition.ConditionalOnProperty; import org.springframework.web.bind.annotation.*;
@RestController @ConditionalOnProperty(name="app.gift.purchases-enabled",havingValue="true") @RequestMapping("/api/v1/public/direct-gifts") public class PublicDirectGiftController {private final DirectGiftFulfillmentService service; public PublicDirectGiftController(DirectGiftFulfillmentService s){service=s;} @PostMapping("/access") public ApiResponse<DirectGiftFulfillmentService.PublicGift> access(@RequestBody Request r){return ApiResponse.of(service.access(r.token()));} public record Request(@NotBlank @Size(max=200) String token){@Override public String toString(){return "DirectGiftAccess[REDACTED]";}}}
